Theorem post_of_tail : forall c1,
  AST SEGTOP_A (rtA_allow Σ) (frmW (tail_post Σ mX B gp s0A s1A s2A s3A s4A s5A s6A s7A s8A s9A s10A s11A F n lo tr))
      (fun mo => ARTM RTA Σ mo /\ PMc mo) c1 ->
